import QtQuick
import Quickshell
import Quickshell.Hyprland
import qs.Commons

// Full-bar option that wraps the stock Omarchy bar instead of forking it.
//
// The stock Bar.qml is loaded straight from $OMARCHY_PATH, so it keeps
// tracking Omarchy updates. This wrapper only edits what the stock bar sees:
//   - widgets listed in a drawer entry's `items` are filtered out of the
//     layout handed to the stock bar, so they leave the bar itself;
//   - the drawer id is added to the widget catalogue, so a
//     `{ "id": "parker.drawer", "items": [...] }` layout entry renders as the
//     drawer button (Drawer.qml), which hosts the tucked widgets in a panel.
//
// Tucked widgets stay in `bar.layout`, so enable state, inline settings and
// `omarchy bar` commands keep working on them exactly as before.
Item {
  id: root

  // Injected by omarchy-shell (see configureBar in shell.qml). barConfig is
  // assigned last, so it doubles as the "fully configured" signal.
  property string omarchyPath: Quickshell.env("OMARCHY_PATH")
  property var shell: null
  property var manifest: null
  property var barWidgetRegistry: null
  property var pluginRegistry: null
  property var barConfig: ({})
  property bool configured: false
  onBarConfigChanged: configured = true

  readonly property string drawerId: manifest && manifest.id ? String(manifest.id) : "parker.drawer"
  readonly property var stockBar: stockLoader.item
  property var drawers: []

  // Read by shell.qml, the bar-state facade and notifications.
  readonly property bool barHidden: stockBar ? stockBar.barHidden === true : false
  readonly property int barSize: stockBar ? stockBar.barSize : 0
  readonly property string fontFamily: stockBar ? stockBar.fontFamily : ""
  readonly property string position: stockBar ? stockBar.position : "top"

  function layoutSection(config, region) {
    var layout = config && Util.isPlainObject(config.layout) ? config.layout : null
    return layout && Array.isArray(layout[region]) ? layout[region] : []
  }

  function entryId(entry) {
    var normalized = Util.normalizeLayoutEntry(entry)
    return normalized ? String(normalized.id) : ""
  }

  function entrySettings(entry) {
    var normalized = Util.normalizeLayoutEntry(entry)
    if (!normalized) return {}
    delete normalized.id
    return normalized
  }

  function findLayoutEntry(config, id) {
    var regions = ["left", "center", "right"]
    for (var r = 0; r < regions.length; r++) {
      var entries = layoutSection(config, regions[r])
      for (var i = 0; i < entries.length; i++)
        if (entryId(entries[i]) === id) return entries[i]
    }
    return null
  }

  // Ordered, de-duplicated widget ids from one drawer's `items` setting.
  // Items are ids ("omarchy.audio") or entries ({ "id": "omarchy.audio", ... }).
  function drawerItemIds(settings) {
    var items = settings && Array.isArray(settings.items) ? settings.items : []
    var ids = []
    for (var i = 0; i < items.length; i++) {
      var id = entryId(items[i])
      if (id && id !== drawerId && ids.indexOf(id) === -1) ids.push(id)
    }
    return ids
  }

  function tuckedIds(config) {
    var out = []
    var regions = ["left", "center", "right"]
    for (var r = 0; r < regions.length; r++) {
      var entries = layoutSection(config, regions[r])
      for (var i = 0; i < entries.length; i++) {
        if (entryId(entries[i]) !== drawerId) continue
        var ids = drawerItemIds(entrySettings(entries[i]))
        for (var j = 0; j < ids.length; j++) if (out.indexOf(ids[j]) === -1) out.push(ids[j])
      }
    }
    return out
  }

  // Settings for a tucked widget: its bar layout entry when it has one,
  // otherwise the inline fields on its object form in `items`.
  function hostedSettings(id, drawerSettings) {
    var entry = findLayoutEntry(barConfig, id)
    if (entry) return entrySettings(entry)
    var items = drawerSettings && Array.isArray(drawerSettings.items) ? drawerSettings.items : []
    for (var i = 0; i < items.length; i++)
      if (Util.isPlainObject(items[i]) && entryId(items[i]) === id) return entrySettings(items[i])
    return {}
  }

  // The bar config the stock bar renders: identical apart from tucked
  // widgets being dropped from the layout.
  readonly property var stockBarConfig: {
    var config = Util.isPlainObject(barConfig) ? barConfig : ({})
    var tucked = tuckedIds(config)
    if (tucked.length === 0 || !Util.isPlainObject(config.layout)) return config
    var copy = Util.cloneJson(config)
    var regions = ["left", "center", "right"]
    for (var r = 0; r < regions.length; r++) {
      if (!Array.isArray(copy.layout[regions[r]])) continue
      copy.layout[regions[r]] = copy.layout[regions[r]].filter(function(entry) {
        return tucked.indexOf(entryId(entry)) === -1
      })
    }
    return copy
  }

  // The host's widget catalogue plus the drawer itself. Flagging the drawer
  // first-party makes the stock bar inject itself as the drawer's `bar`, which
  // is what lets the drawer host widgets the same way the bar's slots do.
  QtObject {
    id: catalogue

    readonly property var widgets: {
      var source = root.barWidgetRegistry ? root.barWidgetRegistry.widgets : null
      var out = {}
      for (var id in source) out[id] = source[id]
      out[root.drawerId] = {
        component: drawerComponent,
        metadata: {
          displayName: "Drawer",
          description: "Tucks chosen widgets into a pop-out panel",
          category: "Layout",
          allowMultiple: true,
          pluginId: root.drawerId,
          firstParty: true
        }
      }
      return out
    }
    readonly property int revision: root.barWidgetRegistry ? root.barWidgetRegistry.revision : 0

    function metadataFor(id) {
      var entry = widgets[String(id || "")]
      return entry ? entry.metadata : null
    }

    function availableIds() {
      return Object.keys(widgets)
    }

    function has(id) {
      return widgets[String(id || "")] !== undefined
    }
  }

  Component {
    id: drawerComponent

    Drawer {
      host: root
    }
  }

  Loader {
    id: stockLoader

    active: root.configured && root.shell !== null
    onActiveChanged: {
      if (!active) return
      setSource(Util.fileUrl(root.omarchyPath + "/shell/plugins/bar/Bar.qml"), {
        omarchyPath: root.omarchyPath,
        shell: root.shell,
        manifest: root.manifest,
        pluginRegistry: root.pluginRegistry,
        barWidgetRegistry: catalogue,
        barConfig: root.stockBarConfig
      })
    }
    onLoaded: {
      item.shell = Qt.binding(function() { return root.shell })
      item.manifest = Qt.binding(function() { return root.manifest })
      item.pluginRegistry = Qt.binding(function() { return root.pluginRegistry })
      item.barConfig = Qt.binding(function() { return root.stockBarConfig })
    }
  }

  // ------------------------------------------------ drawer routing

  function registerDrawer(drawer) {
    if (drawers.indexOf(drawer) === -1) drawers = drawers.concat([drawer])
  }

  function unregisterDrawer(drawer) {
    drawers = drawers.filter(function(item) { return item !== drawer })
  }

  // The drawer hosting `id` on the focused monitor (one drawer is built per
  // monitor), falling back to any drawer that hosts it.
  function drawerFor(id) {
    var monitor = Hyprland.focusedMonitor
    var focused = monitor ? String(monitor.name || "") : ""
    var fallback = null
    for (var i = 0; i < drawers.length; i++) {
      var drawer = drawers[i]
      if (!drawer || !drawer.hosts(id)) continue
      if (drawer.opened && drawer.hostedOpen(id)) return drawer
      if (focused && drawer.screenName === focused) return drawer
      if (!fallback) fallback = drawer
    }
    return fallback
  }

  // ------------------------------------------------ shell.qml surface

  function summonBarWidget(id) {
    var drawer = drawerFor(String(id || ""))
    if (drawer) return drawer.openHosted(String(id))
    return stockBar ? stockBar.summonBarWidget(id) : false
  }

  function hideBarWidget(id) {
    var drawer = drawerFor(String(id || ""))
    if (drawer) return drawer.closeHosted(String(id))
    return stockBar ? stockBar.hideBarWidget(id) : false
  }

  function isBarWidgetOpen(id) {
    var drawer = drawerFor(String(id || ""))
    if (drawer) return drawer.hostedOpen(String(id))
    return stockBar ? stockBar.isBarWidgetOpen(id) : false
  }

  function toggleTransparency() {
    if (stockBar) stockBar.toggleTransparency()
  }

  function debugBarGeometry() {
    return stockBar ? stockBar.debugBarGeometry() : []
  }

  function panelWidgetIdAt(region, index) {
    return stockBar ? stockBar.panelWidgetIdAt(region, index) : ""
  }
}

