cat > shell.qml <<EOF
import QtQuick
import Quickshell
import "file://$P/DrawerModel.js" as DrawerModel

ShellRoot {
  id: shellRoot
  property var results: []
  function check(name, ok) { console.log((ok ? "PASS " : "FAIL ") + name) }

  Component { id: fakeComp; FakeWidget { } }

  QtObject {
    id: fakeBar
    property bool vertical: false
    property int barSize: 26
    property string position: "top"
    property color background: "black"
    property color barForeground: "white"
    property string fontFamily: "monospace"
    property var activePopout: null
    property var barDragSource: null
    property var tooltipTarget: null
    property bool tooltipShown: false
    property string tooltipText: ""
    property var moduleSlots: []
    property var apiCalls: []
    property QtObject barWidgetRegistry: QtObject {
      property var widgets: ({
        "omarchy.audio": { component: fakeComp, metadata: { firstParty: true } },
        "acme.thing": { component: fakeComp, metadata: { firstParty: false } }
      })
    }
    function registerModuleSlot(s) { moduleSlots = moduleSlots.concat([s]) }
    function unregisterModuleSlot(s) { moduleSlots = moduleSlots.filter(function(x) { return x !== s }) }
    function pluginBarApiFor(id, name, reg) { apiCalls = apiCalls.concat([id]); return fakeApi }
    function requestPopout(o) { if (activePopout === o) return; if (activePopout && "close" in activePopout) activePopout.close(); activePopout = o }
    function releasePopout(o) { if (activePopout === o) activePopout = null }
    function showTooltip(t, x) {}
    function hideTooltip(t) {}
    function registerClickTarget(t) {}
    function unregisterClickTarget(t) {}
  }
  QtObject { id: fakeApi; property bool isApi: true; function requestPopout(o) { fakeBar.requestPopout(o) } function releasePopout(o) { fakeBar.releasePopout(o) } }

  QtObject {
    id: fakeHost
    property var barConfig: ({ layout: { left: [], center: [], right: [
      { id: "parker.drawer", items: ["omarchy.audio", "acme.thing", "missing.widget"] },
      { id: "omarchy.audio", step: 5 }, { id: "acme.thing" } ] } })
    property var drawers: []
    function drawerItemIds(s) { return DrawerModel.drawerItemIds(s, "parker.drawer") }
    function hostedSettings(id, s) { return DrawerModel.hostedSettings(barConfig, id, s) }
    function registerDrawer(d) { drawers = drawers.concat([d]) }
    function unregisterDrawer(d) {}
  }

  FakeWidget { id: otherPopout; bar: fakeBar }

  Component.onCompleted: {
    var comp = Qt.createComponent("file://$P/Drawer.qml")
    if (comp.status !== Component.Ready) { console.log("FAIL compile " + comp.errorString()); Qt.quit(); return }
    var d = comp.createObject(null, { host: fakeHost })
    d.bar = fakeBar
    d.settings = { items: ["omarchy.audio", "acme.thing", "missing.widget"] }
    Qt.callLater(function() { Qt.callLater(function() { stage1(d) }) })
  }

  function stage1(d) {
    check("registered with host", fakeHost.drawers.length === 1)
    check("itemIds", JSON.stringify(d.itemIds) === '["omarchy.audio","acme.thing","missing.widget"]')
    check("hosts()", d.hosts("omarchy.audio") && !d.hosts("omarchy.power"))
    var audio = d.hostedItem("omarchy.audio"), thing = d.hostedItem("acme.thing")
    check("hosted items built", !!audio && !!thing && d.hostedItem("missing.widget") === null)
    check("first-party gets real bar", audio.bar === fakeBar)
    check("third-party gets plugin api", thing.bar === fakeApi && fakeBar.apiCalls.indexOf("acme.thing") !== -1)
    check("settings injected from layout entry", audio.settings.step === 5 && audio.moduleName === "omarchy.audio")
    check("slots registered with bar (3 holders)", fakeBar.moduleSlots.length === 3)
    check("drawer starts closed", d.opened === false)

    // unrelated config write should not push settings again
    var pushes = audio.settingsPushes
    var cfg = JSON.parse(JSON.stringify(fakeHost.barConfig)); cfg.position = "bottom"; fakeHost.barConfig = cfg
    check("unrelated config write: no settings push", audio.settingsPushes === pushes)
    cfg = JSON.parse(JSON.stringify(cfg)); cfg.layout.right[1].step = 10; fakeHost.barConfig = cfg
    check("own settings change pushed", audio.settings.step === 10)

    // opening drawer closes an unrelated bar popout
    otherPopout.open()
    d.open()
    check("drawer open", d.opened)
    check("opening drawer closed other popout", !otherPopout.opened && fakeBar.activePopout === null)

    // hosted popout keeps the drawer open
    audio.open()
    check("hosted popout keeps drawer open", d.opened && d.hostedPopoutOpen)
    // another bar popout closes drawer and hosted popouts
    otherPopout.open()
    check("foreign popout closes drawer", !d.opened)
    check("closing drawer closed hosted popout", !audio.opened)
    otherPopout.close()

    // summon path: openHosted while closed opens drawer then widget
    check("openHosted returns true", d.openHosted("omarchy.audio") === true)
    check("openHosted opened drawer", d.opened)
    pendingCheck.drawer = d
    pendingCheck.start()
  }

  Timer {
    id: pendingCheck
    property var drawer
    interval: 150
    onTriggered: {
      var d = drawer, audio = d.hostedItem("omarchy.audio")
      check("openHosted opened widget after delay", audio.opened && d.hostedOpen("omarchy.audio"))
      check("closeHosted", d.closeHosted("omarchy.audio") && !audio.opened && d.opened)
      d.close()
      // widget opened via its own IPC while drawer shut => drawer reopens it
      audio.open()
      check("self-opened hosted widget reopens drawer", d.opened)
      ipcCheck.drawer = d
      ipcCheck.start()
    }
  }

  Timer {
    id: ipcCheck
    property var drawer
    interval: 150
    onTriggered: {
      var d = drawer
      check("hosted widget re-opened inside drawer", d.hostedItem("omarchy.audio").opened)
      fakeBar.barDragSource = otherPopout
      check("bar drag closes drawer", !d.opened)
      fakeBar.barDragSource = null
      d.settings = { items: ["omarchy.audio"] }
      Qt.callLater(function() {
        check("items change rebuilds holders", d.itemIds.length === 1 && fakeBar.moduleSlots.length === 1)
        d.destroy()
        Qt.callLater(function() { check("destroy unregisters slots", fakeBar.moduleSlots.length === 0); Qt.quit() })
      })
    }
  }
}
EOF
