input.command:
cd ~/.config/omarchy/plugins/parker.drawer && python3 - <<'EOF'
p='README.md'; s=open(p).read()
s=s.replace('| `icon`    | `` (…) | Nerd Font glyph for the button  |','| `icon`    | `"\\uf141"` (ellipsis) | Nerd Font glyph for the button |')
open(p,'w').write(s)
EOF
grep -n '`icon`' README.md
T=/tmp/drawer-test/qs; P=$PWD; cat > $T/shell.qml <<EOF
import QtQuick
import Quickshell
import "file://$P/DrawerModel.js" as M
ShellRoot {
  FileView { id: f; path: "$HOME/.config/omarchy/shell.json"; blockLoading: true }
  Component.onCompleted: {
    var bar = JSON.parse(f.text()).bar
    var s = M.stockBarConfig(bar, "parker.drawer")
    for (var r of ["left","center","right"]) console.log("BAR " + r + ": " + s.layout[r].map(M.entryId).join(", "))
    console.log("DRAWER: " + M.drawerItemIds(M.entrySettings(bar.layout.right[1]), "parker.drawer").join(", "))
    Qt.quit()
  }
}
EOF
QT_QPA_PLATFORM=offscreen timeout 15 quickshell -p $T 2>&1 | grep "BAR\|DRAWER\|ERROR"; rm -rf /tmp/drawer-test

